/// `path`'s icon layers, bottom first: glyph, light-theme colour, dark-theme colour. Pierre's
/// order: T3's file names, T3's extensions, then built-in names, then built-in extensions,
/// each extension tried longest first (`d.ts` before `ts`).
pub fn for_path(path: &str) -> &'static [Layer] {
    let name = path.rsplit('/').next().unwrap_or(path).to_lowercase();
    let candidates: Vec<&str> = name.match_indices('.').map(|(i, _)| &name[i + 1..]).collect();
    t3_name(&name)
        .or_else(|| candidates.iter().find_map(|c| t3_extension(c)))
        .or_else(|| built_in_name(&name))
        .or_else(|| candidates.iter().find_map(|c| complete_override(c).or_else(|| built_in_extension(c))))
        .unwrap_or(&SET_76)
}
